# toolkits/bullet_translator/translate_bullet.py
# Mission Veteran AI by G3
# Tool: translate_bullet
#
# Accepts a PII-free military accomplishment bullet and returns an
# ATS-ready civilian resume bullet generated by IBM Granite via watsonx.ai.

import json
import os
import time

from ibm_watsonx_ai import APIClient, Credentials
from ibm_watsonx_ai.foundation_models import ModelInference
from ibm_watsonx_ai.metanames import GenTextParamsMetaNames as GenParams

from shared._common import contains_pii, pii_warning_message, get_credentials
from shared.governance import log_inference, get_subscription_ids

from ibm_watsonx_orchestrate.agent_builder.tools import tool, ToolPermission

_MODEL_ID = "ibm/granite-4-h-small"


@tool(permission=ToolPermission.READ_ONLY)
def translate_bullet(
    bullet: str,
    target_role: str = "general civilian",
    metrics: str = "",
) -> dict:
    """
    Translate a PII-free military accomplishment bullet into an ATS-ready
    civilian resume bullet using IBM Granite via watsonx.ai.

    Args:
        bullet: A single PII-free military accomplishment bullet.
        target_role: The civilian role or career path being targeted
                     (e.g. "Project Management", "IT/Cybersecurity").
        metrics: Optional quantifiable metrics to incorporate
                 (numbers, percentages, dollar amounts).

    Returns:
        A dict with keys: translated_bullet, disclaimer, pii_warning (if any), error (if any).
    """
    # PII guard
    combined = f"{bullet} {metrics}"
    if contains_pii(combined):
        return {
            "translated_bullet": None,
            "disclaimer": None,
            "pii_warning": pii_warning_message(),
        }

    creds = get_credentials()
    client = APIClient(
        credentials=Credentials(url=creds["url"], api_key=creds["api_key"]),
        project_id=creds["project_id"],
    )

    metrics_clause = f"\nAdditional metrics to incorporate: {metrics}" if metrics.strip() else ""

    prompt = f"""You are an expert resume writer helping a U.S. military veteran transition to civilian employment.

Convert the military accomplishment bullet below into ONE ATS-ready civilian resume bullet.
Rules:
- Start with a strong action verb.
- Quantify impact where possible using the provided metrics.
- Remove all military jargon; use plain civilian language.
- Do not invent facts not present in the original bullet or metrics.
- Output exactly one bullet, no preamble, no explanation.

Target civilian role: {target_role}{metrics_clause}

Military bullet:
{bullet}

Civilian resume bullet:"""

    t0 = time.monotonic()
    try:
        model = ModelInference(
            model_id=_MODEL_ID,
            api_client=client,
            params={
                GenParams.MAX_NEW_TOKENS: 120,
                GenParams.TEMPERATURE: 0.3,
                GenParams.STOP_SEQUENCES: ["\n"],
            },
        )
        response = model.generate_text(prompt=prompt)
        latency_ms = (time.monotonic() - t0) * 1000
        translated = response.strip().lstrip("•-– ").strip()

        result = {
            "translated_bullet": translated,
            "disclaimer": (
                "DRAFT – Review before use. Confirm every claim against your "
                "service record before submitting to an employer."
            ),
            "pii_warning": None,
            "error": None,
        }

        # ── Governance: log inference fact ────────────────────────────────
        subs = get_subscription_ids()
        log_inference(
            tool_name="translate_bullet",
            model_id=_MODEL_ID,
            prompt=prompt,
            response=translated,
            input_data={
                "target_role": target_role,
                "has_metrics": bool(metrics.strip()),
            },
            output_data={
                "translated_bullet_length": len(translated),
                "error": None,
            },
            subscription_id=subs.get("translate_bullet"),
            latency_ms=latency_ms,
        )

        return result

    except Exception as exc:
        log_inference(
            tool_name="translate_bullet",
            model_id=_MODEL_ID,
            prompt=prompt,
            response="",
            input_data={"target_role": target_role, "has_metrics": bool(metrics.strip())},
            output_data={"error": str(exc)},
            subscription_id=get_subscription_ids().get("translate_bullet"),
            latency_ms=(time.monotonic() - t0) * 1000,
        )
        return {
            "translated_bullet": None,
            "disclaimer": None,
            "pii_warning": None,
            "error": str(exc),
        }
